export type ArchiveEvidence = { "kind": "archive"; "id": string; "pointer": string; "source_sha256": string; };
export type Claim = { "text": string; "attributed_to": "user" | "agent" | "tool" | "analyst" | "unknown"; "actor_id": (string | null); "speech_act": "request" | "proposal" | "observation" | "interpretation"; "evidence_ids": Array<string>; "origin": "rule" | "llm" | "human"; "review": "candidate" | "accepted" | "rejected"; };
export type ClaimEdit = { "op": "replace_purpose"; "node_id": string; "value": Claim; };
export type ControlEdge = { "kind": "control"; "id": string; "source": string; "target": string; "state": "candidate" | "verified"; "archive_edge_id": (string | null); "explanation": Claim; };
export type Coverage = { "recording_complete": boolean; "selected_source_node_ids": Array<string>; "unassigned_source_node_ids": Array<string>; "omitted_history_artifact_ids": Array<string>; "issues": Array<Issue>; };
export type DataBinding = { "source_node_id": string; "source_output": string; "target_node_id": string; "target_input": string; };
export type DataEdge = { "kind": "data"; "id": string; "source": string; "target": string; "state": "candidate" | "verified"; "archive_edge_id": (string | null); "binding": (DataBinding | null); "explanation": Claim; };
export type DeleteEdge = { "op": "delete_edge"; "edge_id": string; };
export type DependencyProposal = { "source_key": string; "target_key": string; "kind": "data" | "control"; "explanation": ProposalClaim; };
export type EdgeEdit = { "op": "upsert_edge"; "value": (DataEdge | ControlEdge | SemanticEdge); };
export type EventEvidence = { "kind": "event"; "id": string; "artifact_id": string; "line": number; "event_id": string; "pointer": string; "source_sha256": string; };
export type GraphDocument = { "format": "aica-semantic-graph/0.1"; "graph_id": string; "revision_id": string; "parent_revision_id": (string | null); "repository_branch_id": string; "state": "draft" | "accepted"; "executable": false; "source": Source; "parse": ParseInfo; "nodes": Array<Step>; "edges": Array<(DataEdge | ControlEdge | SemanticEdge)>; "variables": Array<Variable>; "evidence": Array<(ArchiveEvidence | EventEvidence)>; "coverage": Coverage; };
export type GraphEditRequest = { "request_id": string; "expected_revision_id": string; "operations": Array<(LabelEdit | ClaimEdit | EdgeEdit | DeleteEdge | ReviewVariable | ReplaceContent)>; };
export type GroupProposal = { "key": string; "kind": "intent" | "decision" | "generation" | "transform" | "composition" | "other"; "label": string; "source_node_ids": Array<string>; "purpose": ProposalClaim; "requirements": Array<ProposalClaim>; "evidence_ids": Array<string>; "prompt_ids"?: Array<string>; "prompts"?: Array<PromptProposal>; "pages"?: Array<PageProposal>; };
export type Issue = { "id": string; "code": string; "severity": "warning" | "error"; "message": string; "node_ids": Array<string>; "evidence_ids": Array<string>; };
export type JsonValue = unknown;
export type LabelEdit = { "op": "set_label"; "node_id": string; "value": string; };
export type LayoutPosition = { "node_id": string; "x": number; "y": number; };
export type LayoutUpdate = { "request_id": string; "graph_revision_id": string; "expected_layout_version": number; "positions": Array<LayoutPosition>; };
export type ModelProposal = { "groups": Array<GroupProposal>; "edges": Array<(DependencyProposal | SemanticProposal)>; "variables": Array<VariableProposal>; "unresolved": Array<Issue>; };
export type ModuleImageEdit = { "id": string; "original_artifact_id": string; "result_artifact_id": string; "instruction": string; "region"?: (Array<number> | null); "model": string; "source": string; };
export type ModulePage = { "id": string; "label": string; "page_number"?: (number | null); "summary": Claim; "prompts"?: Array<ModulePrompt>; "artifact_ids": Array<string>; "evidence_ids": Array<string>; };
export type ModulePrompt = { "text": string; "kind": "recorded" | "consolidated" | "suggested" | "edited"; "evidence_ids": Array<string>; "source_pointer"?: (string | null); };
export type PagePromptProposal = { "text": string; "kind": "consolidated" | "suggested"; };
export type PageProposal = { "source_page_id": string; "summary": string; "prompts"?: Array<PagePromptProposal>; };
export type ParseInfo = { "parser_version": string; "prompt_version": string; "model": (string | null); "mode": "rules_only" | "rules_llm" | "human_annotated_fixture"; "input_sha256": string; };
export type PromptProposal = { "text": string; "kind": "consolidated" | "suggested"; "evidence_ids": Array<string>; };
export type ProposalClaim = { "text": string; "attributed_to": "user" | "agent" | "tool" | "analyst" | "unknown"; "actor_id": (string | null); "speech_act": "request" | "proposal" | "observation" | "interpretation"; "evidence_ids": Array<string>; "origin": "llm"; "review": "candidate"; };
export type ReplaceContent = { "op": "replace_content"; "nodes": Array<Step>; "edges": Array<(DataEdge | ControlEdge | SemanticEdge)>; "variables": Array<Variable>; };
export type ReviewVariable = { "op": "review_variable"; "variable_id": string; "review": "accepted" | "rejected"; };
export type SemanticEdge = { "kind": "semantic"; "id": string; "source": string; "target": string; "relation": "refines" | "alternative_to" | "continues" | "inspired_by" | "supports"; "explanation": Claim; };
export type SemanticProposal = { "source_key": string; "target_key": string; "kind": "semantic"; "relation": "refines" | "alternative_to" | "continues" | "inspired_by" | "supports"; "explanation": ProposalClaim; };
export type Source = { "import_id": string; "archive_sha256": string; "archive_revision_id": string; "snapshot_id": string; "stream_id": string; "through_seq": number; };
export type Step = { "id": string; "kind": "intent" | "decision" | "generation" | "transform" | "composition" | "other"; "label": string; "purpose": Claim; "requirements": Array<Claim>; "source_node_ids": Array<string>; "run_ids": Array<string>; "artifact_ids": Array<string>; "evidence_ids": Array<string>; "prompts"?: Array<ModulePrompt>; "pages"?: Array<ModulePage>; "image_edits"?: Array<ModuleImageEdit>; };
export type ValueLocator = { "source_node_id": string; "evidence_id": string; "pointer": string; "decode": "identity" | "json_string"; "value_pointer": string; };
export type Variable = { "id": string; "step_id": string; "label": string; "description": Claim; "locator": ValueLocator; "value_type": "string" | "array" | "number" | "integer" | "boolean" | "object"; "current_value": JsonValue; "allowed_modes": Array<"keep" | "override" | "append">; "separator": (string | null); "review": "candidate" | "accepted" | "rejected"; };
export type VariableProposal = { "group_key": string; "label": string; "locator": ValueLocator; "description": ProposalClaim; };
